const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const titles={home:['Let’s Make This Diwali Greener.','WELCOME'],air:['Check Your Air','AIR AROUND YOU'],planner:['Your Diwali, Your Air','DIWALI PLANNER'],community:['Green Diwali Community','GROW TOGETHER'],whatif:['What If...?','EXPLORE A SCENARIO'],map:['Explore Pollution Map','NEARBY STATIONS'],alerts:['My Alerts','AIR UPDATES'],progress:['My Progress','YOUR PARTICIPATION'],science:['Where Does Our Data Come From?','SCIENCE & DATA'],accuracy:['How Accurate Is Our Prediction?','SCIENCE & DATA'],explain:['Why Is This Happening?','SCIENCE & DATA'],authority:['City Action Centre','CITY ACTION CENTRE']};
const store={userId:localStorage.getItem('vayuUserId')||('n'+crypto.randomUUID().replaceAll('-','')),name:localStorage.getItem('vayuName')||'Green Neighbour',communityId:null,aq:null};localStorage.setItem('vayuUserId',store.userId);
$('#display-name').value=store.name;$('#display-name').onchange=e=>{store.name=e.target.value.trim()||'Green Neighbour';localStorage.setItem('vayuName',store.name)};
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3600)}
async function api(path,opts={}){let r=await fetch(path,opts);let d=await r.json();if(!r.ok)throw Error(d.detail||d.message||`Request failed (${r.status})`);return d}
const json=(method,data)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
function person(){return {user_id:store.userId,display_name:store.name}}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function page(v){if(!titles[v])return;$$('main > .view').forEach(e=>e.style.display='none');$('#detail').style.display=v==='home'?'none':'block';$('#home-view').style.display=v==='home'?'':'none';$('#title').textContent=titles[v][0];$('#crumb').textContent=titles[v][1];$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));if(v==='home')return;if(v==='community')communityPage('browse');else if(v==='air')airPage();else if(v==='planner')plannerPage();else if(v==='whatif')whatIfPage();else if(v==='map')mapPage();else if(v==='alerts')alertsPage();else if(v==='progress')progressPage();else if(v==='authority')authorityPage();else if(v==='science'||v==='accuracy'||v==='explain')sciencePage(v)}
function navButtons(){return `<div class="subnav">${[['browse','Find a community'],['challenges','Green challenges'],['pledge','Take the pledge'],['events','Community events'],['leaderboard','Friendly leaderboard'],['feed','Community feed']].map(([x,label])=>`<button data-tab="${x}" class="${communityTab===x?'selected':''}">${label}</button>`).join('')}</div>`}
let communityTab='browse';
function communityPage(tab='browse'){communityTab=tab;const d=$('#detail');d.innerHTML=`<section class="community-hero"><div class="welcome-kicker">SMALL ACTIONS, SHARED JOY</div><h2>A greener Diwali<br>starts <em>with us.</em></h2><p>Meet people nearby, try practical green challenges, and celebrate the good ideas your community shares.</p><div class="community-mode">Local community space · no login or staffed moderation · display names are self-chosen and not verified</div></section>${navButtons()}<section id="community-content"></section>`;$$('[data-tab]').forEach(b=>b.onclick=()=>communityPage(b.dataset.tab));renderCommunityTab(tab)}
async function renderCommunityTab(tab){let el=$('#community-content');if(tab==='browse'){let [cs,ms]=await Promise.all([api('/api/community/communities'),api('/api/community/memberships?user_id='+encodeURIComponent(store.userId))]);let joined=new Set(ms.map(c=>c.id));el.innerHTML=`<div class="split-head"><div><h2>Find your people</h2><p>Browse groups by name or city. Communities are created by neighbours and have not been independently verified.</p></div><button class="btn btn-primary" id="create-community-open">+ Create a community</button></div><div class="community-search"><input id="community-search" placeholder="Search a name or city" aria-label="Search communities"><button class="btn btn-outline" id="search-communities">Search</button></div><div class="community-list" id="community-list">${communityCards(cs,joined)}</div><div class="form-card hidden" id="community-form"><h3>Create a community</h3><p>Your public group will be saved in this local community space.</p><form id="create-community"><input required minlength="3" maxlength="80" name="name" placeholder="Community name"><input required minlength="2" maxlength="80" name="city" placeholder="City or area"><textarea required minlength="10" maxlength="500" name="description" placeholder="What brings your community together?"></textarea><button class="btn btn-primary">Create community</button></form></div>`;$('#create-community-open').onclick=()=>$('#community-form').classList.toggle('hidden');$('#search-communities').onclick=()=>searchCommunity();$('#community-search').onkeydown=e=>{if(e.key==='Enter')searchCommunity()};$('#create-community').onsubmit=async e=>{e.preventDefault();try{let f=new FormData(e.target);await api('/api/community/communities',json('POST',Object.fromEntries(f)));toast('Community created. Invite neighbours to join.');communityPage('browse')}catch(err){toast(err.message)}};bindJoins(joined)}else if(tab==='challenges'){let [cs,ch]=await Promise.all([api('/api/community/memberships?user_id='+encodeURIComponent(store.userId)),api('/api/community/challenges?user_id='+encodeURIComponent(store.userId))]);el.innerHTML=`<div class="split-head"><div><h2>Green challenges</h2><p>Try an activity that fits your celebration. Points celebrate participation; they do not measure pollution reduction.</p></div><select id="challenge-community" class="control"><option value="">No community selected</option>${cs.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="challenge-grid">${ch.map(x=>`<article class="challenge-card"><span class="challenge-points">${x.points} points</span><div class="challenge-icon">${x.kind==='pledge'?'♡':x.kind==='community'?'✿':'✳'}</div><h3>${esc(x.name)}</h3><p>${esc(x.description)}</p><button class="btn ${x.completed?'btn-done':'btn-outline'}" data-challenge="${x.id}" ${x.completed?'disabled':''}>${x.completed?'Completed ✓':'I did this'}</button></article>`).join('')}</div>`;$$('[data-challenge]').forEach(b=>b.onclick=async()=>{try{let r=await api('/api/community/challenges/complete',json('POST',{...person(),challenge_id:b.dataset.challenge,community_id:$('#challenge-community').value?Number($('#challenge-community').value):null}));toast(r.already_completed?'Already counted — thanks for taking part.':`Added ${r.new_points} participation points.`);communityPage('challenges')}catch(e){toast(e.message)}})}else if(tab==='pledge'){let [p,cs,pr]=await Promise.all([api('/api/community/pledges'),api('/api/community/memberships?user_id='+encodeURIComponent(store.userId)),api('/api/community/progress?user_id='+encodeURIComponent(store.userId))]);el.innerHTML=`<article class="pledge-card"><div class="eyebrow">A THOUGHTFUL PROMISE</div><h2>My Green Diwali pledge</h2><blockquote>“This Diwali, I will make thoughtful choices, reduce unnecessary waste, and encourage my community to celebrate responsibly.”</blockquote><label class="form-label">Share your pledge with a community (optional)<select id="pledge-community" class="control"><option value="">No community selected</option>${cs.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><button id="pledge-button" class="btn btn-primary" ${pr.pledged?'disabled':''}>${pr.pledged?'I’ve taken the pledge ✓':'Take the pledge · 10 points'}</button><div class="pledge-count"><b>${p.count}</b><span>pledges saved in this community space</span></div><small>One pledge per local profile. Counts show participation, not environmental impact.</small><button id="share-pledge" class="btn btn-outline">Share the pledge</button></article>`;$('#pledge-button').onclick=async()=>{try{let id=$('#pledge-community').value;let r=await api('/api/community/pledges',json('POST',{...person(),community_id:id?+id:null}));toast(r.already_pledged?'Your pledge is already counted.':'Your pledge is saved. Thank you!');communityPage('pledge')}catch(e){toast(e.message)}};$('#share-pledge').onclick=()=>share('This Diwali, I will make thoughtful choices, reduce unnecessary waste, and encourage my community to celebrate responsibly. #GreenDiwali')}
else if(tab==='events'){let [events,cs]=await Promise.all([api('/api/community/events?user_id='+encodeURIComponent(store.userId)),api('/api/community/memberships?user_id='+encodeURIComponent(store.userId))]);el.innerHTML=`<div class="split-head"><div><h2>Community events</h2><p>Neighbour-created events. Organisers are self-declared; check details locally before attending.</p></div><button class="btn btn-primary" id="new-event">+ Create an event</button></div><div class="form-card hidden" id="event-form"><h3>Share an event</h3><form id="create-event"><select required name="community_id" class="control"><option value="">Choose community</option>${cs.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><input required name="name" maxlength="100" placeholder="Event name"><textarea required name="description" maxlength="800" placeholder="What will happen?"></textarea><label>Date and time <input required name="starts_at" type="datetime-local" class="control"></label><input required name="location" maxlength="180" placeholder="Location"><button class="btn btn-primary">Post event</button></form></div><div class="event-list">${events.length?events.map(eventCard).join(''):'<div class="empty-card"><div>✿</div><h3>No events posted yet</h3><p>When a neighbour creates an event, it will appear here.</p></div>'}</div>`;$('#new-event').onclick=()=>$('#event-form').classList.toggle('hidden');$('#create-event').onsubmit=async e=>{e.preventDefault();try{let f=Object.fromEntries(new FormData(e.target));f.community_id=+f.community_id;f.starts_at=new Date(f.starts_at).toISOString();await api('/api/community/events',json('POST',{...person(),...f}));toast('Event created and saved.');communityPage('events')}catch(err){toast(err.message)}};$$('[data-event-join]').forEach(b=>b.onclick=async()=>{try{let r=await api(`/api/community/events/${b.dataset.joined==='true'?'leave':'join'}`,json('POST',{...person(),event_id:+b.dataset.eventJoin}));toast(r.message|| (r.already_joined?'You already joined this event.':'You’re on the participant list. +30 participation points'));communityPage('events')}catch(e){toast(e.message)}})}
else if(tab==='leaderboard'){let [ind,com]=await Promise.all([api('/api/community/leaderboard?period=overall&scope=individual'),api('/api/community/leaderboard?period=overall&scope=community')]);el.innerHTML=`<div class="split-head"><div><h2>Celebrate participation</h2><p>Rankings come from saved points. Names are self-selected and unverified. Points do not represent pollution reduction.</p></div><select id="leader-scope" class="control"><option value="individual">Neighbours</option><option value="community">Communities</option></select><select id="leader-period" class="control"><option value="overall">All time</option><option value="weekly">Last 7 days</option></select></div><div id="leaderboard-list">${leaderTable(ind,'individual')}</div>`;$('#leader-scope').onchange=refreshBoard;$('#leader-period').onchange=refreshBoard}
else if(tab==='feed'){let [posts,cs]=await Promise.all([api('/api/community/feed'),api('/api/community/memberships?user_id='+encodeURIComponent(store.userId))]);el.innerHTML=`<div class="split-head"><div><h2>Neighbourhood notes</h2><p>Posts are saved locally. Profiles are not verified and reports are stored for review; no moderation team is connected.</p></div></div><form id="new-post" class="post-compose"><select id="post-community" class="control"><option value="">Open Green Community</option>${cs.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><textarea id="post-content" required maxlength="1000" placeholder="Share a green celebration idea…"></textarea><div class="post-compose-bottom"><label class="upload-label">Add a picture <input id="post-image" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="btn btn-primary">Share with community</button></div></form><div class="feed-list">${posts.length?posts.map(postCard).join(''):'<div class="empty-card"><div>♡</div><h3>Your community feed starts here</h3><p>Share a helpful green idea to get the conversation started.</p></div>'}</div>`;$('#new-post').onsubmit=async e=>{e.preventDefault();try{let image_url=null,file=$('#post-image').files[0];if(file){let fd=new FormData();fd.append('file',file);let up=await fetch('/api/community/uploads',{method:'POST',body:fd});let ud=await up.json();if(!up.ok)throw Error(ud.detail);image_url=ud.image_url}let id=$('#post-community').value;await api('/api/community/posts',json('POST',{...person(),community_id:id?+id:null,content:$('#post-content').value,image_url}));toast('Post saved to your community feed.');communityPage('feed')}catch(err){toast(err.message)}};bindPostActions()}}
function communityCards(cs,joined){return cs.length?cs.map(c=>`<article class="group-card"><div class="group-icon">✿</div><div class="group-info"><h3>${esc(c.name)}</h3><span>⌖ ${esc(c.city)} · ${c.members} ${c.members===1?'member':'members'}</span><p>${esc(c.description)}</p></div><button class="btn ${joined.has(c.id)?'btn-done':'btn-outline'}" data-join="${c.id}" data-joined="${joined.has(c.id)}">${joined.has(c.id)?'Joined ✓':'Join group'}</button></article>`).join(''):'<div class="empty-card"><div>♡</div><h3>No communities yet</h3><p>There are no active groups in this local space. Create one and invite your neighbours.</p><button class="btn btn-primary" id="empty-create">Create a community</button></div>'}
function bindJoins(joined){$$('[data-join]').forEach(b=>b.onclick=async()=>{try{let cid=b.dataset.join,verb=b.dataset.joined==='true'?'leave':'join';await api(`/api/community/communities/${cid}/${verb}`,json('POST',person()));toast(verb==='join'?'You joined the community.':'You left the community.');communityPage('browse')}catch(e){toast(e.message)}});if($('#empty-create'))$('#empty-create').onclick=()=>{$('#community-form').classList.remove('hidden');$('#create-community-open')?.scrollIntoView({behavior:'smooth'})}}
async function searchCommunity(){let q=$('#community-search').value;let cs=await api('/api/community/communities?q='+encodeURIComponent(q));let ms=await api('/api/community/memberships?user_id='+encodeURIComponent(store.userId));$('#community-list').innerHTML=communityCards(cs,new Set(ms.map(x=>x.id)));bindJoins(new Set(ms.map(x=>x.id)))}
function eventCard(e){let dt=new Date(e.starts_at);return `<article class="event-card"><div class="event-date"><b>${isNaN(+dt)?'—':dt.toLocaleDateString(undefined,{day:'2-digit'})}</b><span>${isNaN(+dt)?'DATE':dt.toLocaleDateString(undefined,{month:'short'})}</span></div><div class="event-info"><span class="event-community">${esc(e.community_name)}</span><h3>${esc(e.name)}</h3><p>${esc(e.description)}</p><small>${dt.toLocaleString()} · ${esc(e.location)} · Organised by ${esc(e.organiser_name)}</small><small>${e.participants} participant${e.participants===1?'':'s'}</small></div><button class="btn ${e.joined?'btn-done':'btn-outline'}" data-event-join="${e.id}" data-joined="${e.joined}">${e.joined?'Leave event':'Join event · 30 points'}</button></article>`}
function leaderTable(rows,scope){return rows.length?`<table class="community-table"><thead><tr><th>Rank</th><th>${scope==='individual'?'Neighbour':'Community'}</th><th>Points</th><th>Activities</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.rank}</td><td>${esc(r.display_name||r.name)}</td><td>${r.points}</td><td>${r.activities}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-card"><div>★</div><h3>No points on the board yet</h3><p>Take part in a challenge or event to get things started.</p></div>'}
async function refreshBoard(){try{let scope=$('#leader-scope').value,period=$('#leader-period').value;let rows=await api(`/api/community/leaderboard?scope=${scope}&period=${period}`);$('#leaderboard-list').innerHTML=leaderTable(rows,scope)}catch(e){toast(e.message)}}
function postCard(p){return `<article class="feed-post"><div class="post-head"><span class="profile-icon">✿</span><span><b>${esc(p.display_name)}</b><small>${esc(p.community_name)} · ${new Date(p.created_at).toLocaleString()}</small></span><button class="report-button" data-report="${p.id}">Report</button></div><p>${esc(p.content)}</p>${p.image_url?`<img class="post-image" src="${esc(p.image_url)}" alt="Image shared by a community member">`:''}<div class="post-actions"><button data-like="${p.id}">♡ ${p.likes} like${p.likes===1?'':'s'}</button><span> ${p.comments_count} comments</span><button data-comment="${p.id}">Comment</button></div><div class="comment-list">${(p.comments||[]).map(c=>`<p><b>${esc(c.display_name)}</b> ${esc(c.content)}</p>`).join('')}</div></article>`}
function bindPostActions(){$$('[data-like]').forEach(b=>b.onclick=async()=>{try{await api('/api/community/likes',json('POST',{...person(),post_id:+b.dataset.like}));communityPage('feed')}catch(e){toast(e.message)}});$$('[data-report]').forEach(b=>b.onclick=async()=>{let reason=prompt('Why are you reporting this post?');if(!reason)return;try{await api('/api/community/reports',json('POST',{...person(),kind:'post',item_id:+b.dataset.report,reason}));toast('Report saved locally as pending review.')}catch(e){toast(e.message)}});$$('[data-comment]').forEach(b=>b.onclick=async()=>{let content=prompt('Write a comment');if(!content)return;try{await api('/api/community/comments',json('POST',{...person(),post_id:+b.dataset.comment,content}));toast('Comment saved.');communityPage('feed')}catch(e){toast(e.message)}})}
async function share(text){try{if(navigator.share)await navigator.share({text});else if(navigator.clipboard){await navigator.clipboard.writeText(text);toast('Pledge copied to clipboard.')}else toast(text)}catch(e){}}

function airPage(){const a=store.aq?.current,kind=a?.kind||store.aq?.data_kind||'unavailable',label=kind==='observed'?'Observed':kind==='forecast'?'Forecast':kind==='estimated'?'Estimated':'Unavailable',explanation=kind==='observed'?'Imported observation. Check its station and source details before treating it as a local reading.':kind==='estimated'?'Open-Meteo model estimate for a wider area, not a nearby monitoring-station measurement.':kind==='forecast'?'Open-Meteo forecast for a wider area, not a sensor measurement.':'We couldn’t retrieve the latest air-quality value.';$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">YOUR LOCAL AIR UPDATE</div><h2>Check Your Air</h2><p>Current data comes from Open-Meteo model estimates unless an imported station observation is available. There is no live connection to a verified local monitoring station.</p></section><div class="air-summary"><article class="air-card"><div class="eyebrow">LATEST AVAILABLE PM₂.₅ · <span class="data-kind ${esc(kind)}">${label}</span></div><div class="air-reading"><strong>${a&&Number.isFinite(Number(a.pm25))?Number(a.pm25).toFixed(1):'—'}</strong><span>µg/m³ · PM₂.₅</span></div><p>${explanation}</p><small class="updated-label">${esc(a?.timestamp||'No timestamp available')} · ${esc(a?.source||store.aq?.source||'No source available')} · ${esc(a?.location||store.aq?.location||'Location unavailable')}</small><div class="air-advice">AQI unavailable — this app has no valid supported AQI value or documented calculation for this reading.</div></article><article class="tomorrow-card"><div class="eyebrow"><span class="data-kind forecast">Forecast</span> · NOT A MEASUREMENT</div><h3>Tomorrow’s Air</h3><div class="tomorrow-summary">${esc($('#tomorrow-summary').textContent)}</div><p>${esc($('#tomorrow-detail').textContent)}</p></article></div><article class="page-card"><h3>Recent air updates</h3><div class="plain-list">${store.aq?.series?.length?store.aq.series.slice(-12).map(x=>{const rowKind=x.kind||'estimated',rowLabel=rowKind==='forecast'?'Forecast':rowKind==='observed'?'Observed':'Estimated';return `<div><b>${esc(x.timestamp)}</b><span>PM₂.₅ ${Number(x.pm25).toFixed(1)} · PM₁₀ ${Number(x.pm10).toFixed(1)} µg/m³</span><small><span class="data-kind ${rowKind}">${rowLabel}</span> · ${esc(x.source||'Source unavailable')} · ${esc(x.location||'Location unavailable')}</small></div>`}).join(''):'<div class="empty-card"><h3>No readings to show</h3><p>Try again later or connect a supported data source. We do not fill gaps with made-up values.</p><button class="btn btn-outline" data-refresh-air>Try again</button></div>'}</div></article>`;$('#detail').querySelector('[data-refresh-air]')?.addEventListener('click',loadAir)}
function plannerPage(){
 Promise.all([api('/api/historical/coverage'),api('/api/historical/diwali-dates')]).then(([coverage,calendar])=>{
  const stations=coverage.observations||[],cities=[...new Set(stations.map(x=>x.city))];
  const opts=cities.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');
  const years=calendar.dates.map(x=>`<label class="year-choice"><input type="checkbox" name="hist-year" value="${x.year}" ${x.year<2024?'checked':''}><span>${x.year}${x.status==='upcoming'?' · upcoming':''}</span></label>`).join('');
  const inventory=stations.length?`<div class="coverage-list">${stations.map(s=>`<article class="coverage-item"><b>${esc(s.city)} · ${esc(s.station)}</b><span>${s.records} observed day(s) · ${s.start} to ${s.end}</span><small>PM₂.₅ ${s.pm25_days} days · PM₁₀ ${s.pm10_days} days · AQI ${s.aqi_days} days</small><small>Diwali windows with any records: ${(s.available_diwali_years||[]).join(', ')||'none'} · Source: ${esc((s.sources||[]).join(', ')||'not supplied')}</small></article>`).join('')}</div>`:'<div class="empty-card"><h3>No historical station records imported</h3><p>The comparison only uses daily records imported on this device. Current model estimates and forecasts are shown separately and are not treated as historical observations.</p></div>';
  $('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">DIWALI COMPARISON · <span class="data-kind observed">Observed</span></div><h2>Compare air across Diwali years</h2><p>Choose one city and station, then compare the same number of days around each year’s reference Diwali date. Missing values remain missing; source and coverage details stay visible.</p></section><article class="page-card"><div class="historical-controls"><label>City<select id="hist-city" class="control"><option value="">${cities.length?'Choose a city':'No cities imported yet'}</option>${opts}</select></label><label>Monitoring station<select id="hist-station" class="control" disabled><option value="">Choose a city first</option></select></label><label>Days before and after<select id="hist-days" class="control"><option value="1">1 day each side</option><option value="2">2 days each side</option><option value="3" selected>3 days each side</option><option value="5">5 days each side</option><option value="7">7 days each side</option></select></label></div><div class="year-select"><b>Choose at least two years</b><div>${years}</div></div><button class="btn btn-primary" id="run-historical" ${stations.length?'':'disabled'}>Compare selected years</button><div id="historical-results" class="history-output"><div class="empty-card"><h3>${coverage.records_loaded?`${coverage.records_loaded} daily records are loaded`:'Import daily station data to start comparing'}</h3><p>${coverage.records_loaded?`${coverage.city_station_pairs} city/station pair(s) available. Choose a city, station, and at least two years.`:'No city or station data is preloaded. Do not enter estimated or forecast values as station observations.'}</p></div></div></article><article class="page-card"><h3>Data currently available on this device</h3><p>${coverage.records_loaded?`${coverage.records_loaded} observed daily records across ${coverage.city_station_pairs} city/station pair(s). PM₂.₅/PM₁₀ unit: µg/m³. AQI is unitless.`:'0 daily historical observations. No cities, stations, years, pollutants, or source datasets have been imported yet.'}</p>${inventory}<p class="data-note">Source names and URLs are provided by the uploader, not verified by this app. Choose the same physical station for each year where possible.</p><p><a href="https://app.cpcbccr.com/AQIIndia" target="_blank" rel="noopener">CPCB National AQI dashboard</a> provides current station/AQI information. The <a href="https://tn.data.gov.in/catalog/historical-daily-ambient-air-quality-data" target="_blank" rel="noopener">OGD historical daily catalog</a> describes SO₂, NO₂, RSPM and SPM and lists a 2017 update; that does not establish PM₂.₅, PM₁₀, or AQI coverage for 2022–2026. Do not relabel RSPM/SPM as PM₁₀.</p><div class="table-wrap"><table class="community-table"><thead><tr><th>Year</th><th>Reference Diwali date</th><th>Status as of ${calendar.as_of}</th><th>Date source</th></tr></thead><tbody>${calendar.dates.map(x=>`<tr><td>${x.year}</td><td>${x.date}</td><td>${x.status==='upcoming'?'Upcoming — no full festival observations yet':'Past reference date'}</td><td><a href="${esc(x.source_url)}" target="_blank" rel="noopener">Source</a></td></tr>`).join('')}</tbody></table></div><small>Dates are reference dates; regional observance may differ. Comparisons use each year’s listed date and show the exact ranges in the results.</small></article><article class="page-card"><h3>Import daily station observations</h3><p>Use one row per city, station, and local calendar date. Required headers: <code>date,city,station</code> and at least one of <code>pm25,pm10,aqi</code>. A timestamp column may replace date. PM₂.₅/PM₁₀ must be in µg/m³; AQI must be a source-reported integer from 0–500. If a source is hourly, prepare its documented daily statistic before import. This tool does not aggregate hourly readings or calculate AQI.</p><p>Use the official station name consistently. Future dates are rejected; duplicate city/station/date rows are skipped and do not overwrite saved rows.</p><form id="historical-upload" class="history-upload"><label>Source name<input class="control" name="source_name" required maxlength="200" placeholder="e.g. CPCB station export"></label><label>Source page or file URL<input class="control" name="source_url" type="url" maxlength="500" placeholder="https://… (optional)"></label><label>PM₂.₅ / PM₁₀ unit<select class="control" name="unit" required><option value="ug/m3">µg/m³ (micrograms per cubic metre)</option></select></label><label>Daily CSV<input class="control" id="historical-file" name="file" type="file" accept=".csv,text/csv" required></label><button class="btn btn-outline" id="validate-historical">Validate CSV</button><button class="btn btn-primary" id="import-historical" type="button" disabled>Import validated rows</button><span id="historical-upload-result" role="status" aria-live="polite"></span></form><div id="historical-preview" class="history-validation" role="status" aria-live="polite">Validation checks dates, non-empty city/station names, pollutant columns, values, units, and duplicates before saving.</div></article>`;
  const city=$('#hist-city'),station=$('#hist-station');
  function updateStations(){const selected=stations.filter(x=>x.city===city.value);station.innerHTML=selected.length?selected.map(x=>`<option value="${esc(x.station)}">${esc(x.station)} · ${x.records} observed days</option>`).join(''):'<option value="">No stations for this city</option>';station.disabled=!selected.length}
  city.onchange=updateStations;if(cities.length){city.value=cities[0];updateStations()}
  $('#run-historical').onclick=async()=>{const selected=$$('input[name="hist-year"]:checked').map(x=>x.value);if(!city.value||!station.value)return toast('Choose a city and monitoring station with imported records.');if(selected.length<2)return toast('Select at least two years.');try{const q=new URLSearchParams({city:city.value,station:station.value,years:selected.join(','),days:$('#hist-days').value});const data=await api('/api/historical/diwali?'+q);$('#historical-results').innerHTML=renderHistorical(data);$('#diwali-metric').onchange=()=>drawDiwaliChart(data);drawDiwaliChart(data)}catch(e){toast(e.message)}};
  const upload=$('#historical-upload'),file=$('#historical-file'),importButton=$('#import-historical'),preview=$('#historical-preview'),result=$('#historical-upload-result');let validatedFile='';
  file.onchange=()=>{validatedFile='';importButton.disabled=true;preview.textContent='File changed. Validate it before importing.';result.textContent=''};
  upload.onsubmit=async e=>{e.preventDefault();validatedFile='';importButton.disabled=true;preview.textContent='Checking file…';try{const info=await api('/api/historical/validate',{method:'POST',body:new FormData(upload)});preview.innerHTML=`<b>Validation summary</b><ul><li>${info.valid_rows} valid unique row(s); ${info.new_rows} new row(s) to save</li><li>${info.rejected_rows} invalid row(s); ${info.duplicate_rows_in_file} duplicate row(s) inside this CSV; ${info.duplicate_rows_already_saved} already saved</li><li>Dates: ${esc(info.date_from||'—')} to ${esc(info.date_to||'—')}</li><li>Station(s): ${info.stations.map(x=>`${esc(x.city)} · ${esc(x.station)}`).join(', ')||'none'}</li><li>Valid readings: PM₂.₅ ${info.valid_metric_days.pm25}, PM₁₀ ${info.valid_metric_days.pm10}, AQI ${info.valid_metric_days.aqi}</li><li>Units: ${esc(info.unit)} for PM; AQI is unitless</li></ul><small>${esc(info.warning)}</small>`;validatedFile=file.files[0]?.name||'';importButton.disabled=!info.new_rows;result.textContent=info.new_rows?'Review the summary, then import valid rows.':'Nothing new to import.'}catch(err){preview.innerHTML=`<b>Could not validate this file</b><p>${esc(err.message)}</p>`;result.textContent='Correct the file or source information and validate again.'}};
  importButton.onclick=async()=>{if(!validatedFile||file.files[0]?.name!==validatedFile)return toast('Validate the currently selected file first.');importButton.disabled=true;try{const out=await api('/api/historical/import',{method:'POST',body:new FormData(upload)});result.textContent=`Imported ${out.imported}; rejected ${out.rejected}; duplicate ${out.duplicates}. ${out.provenance}`;toast(`${out.imported} observed daily record(s) imported.`);plannerPage()}catch(err){result.textContent=err.message;importButton.disabled=false}};
 }).catch(e=>{$('#detail').innerHTML=`<div class="empty-card"><h3>Historical comparison is unavailable</h3><p>${esc(e.message)}</p><button class="btn btn-outline" onclick="location.reload()">Try again</button></div>`})
}
function drawDiwaliChart(data){
 const svg=$('#diwali-chart'),metric=$('#diwali-metric')?.value||'pm25';if(!svg)return;
 const metrics={pm25:'PM₂.₅ (µg/m³)',pm10:'PM₁₀ (µg/m³)',aqi:'AQI'};
 const periods=[['before','Before'],['during','Diwali day'],['after','After']];
 const W=760,H=280,L=54,R=18,T=18,B=46,plotW=W-L-R,plotH=H-T-B;
 const values=data.results.flatMap(y=>periods.map(([k])=>y.windows[k].metrics[metric]?.mean)).filter(v=>Number.isFinite(v));
 svg.innerHTML='';svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
 if(!values.length){svg.innerHTML=`<text x="${W/2}" y="${H/2}" text-anchor="middle">No ${metrics[metric]} observations for these years</text>`;return}
 const max=Math.max(1,...values)*1.18,y=v=>T+plotH-(v/max)*plotH,x=i=>L+plotW*i/(periods.length-1);
 for(let i=0;i<5;i++){const val=max*(1-i/4),yy=T+plotH*i/4;svg.insertAdjacentHTML('beforeend',`<line x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}" class="chart-gridline"/><text x="${L-10}" y="${yy+4}" text-anchor="end" class="chart-axis-label">${val.toFixed(max<20?1:0)}</text>`)}
 periods.forEach(([k,label],i)=>svg.insertAdjacentHTML('beforeend',`<text x="${x(i)}" y="${H-12}" text-anchor="middle" class="chart-axis-label">${label}</text>`));
 const colors=['#285f3f','#bf6f3d','#538d61','#d49a3c','#76937a'];
 data.results.forEach((year,yi)=>{const vals=periods.map(([k])=>year.windows[k].metrics[metric]?.mean),color=colors[yi%colors.length];
  for(let i=0;i<vals.length-1;i++)if(Number.isFinite(vals[i])&&Number.isFinite(vals[i+1]))svg.insertAdjacentHTML('beforeend',`<line x1="${x(i)}" y1="${y(vals[i])}" x2="${x(i+1)}" y2="${y(vals[i+1])}" stroke="${color}" stroke-width="3" stroke-linecap="round"/>`);
  vals.forEach((v,i)=>{if(Number.isFinite(v)){const w=year.windows[periods[i][0]],valid=w.metrics[metric].valid_days;svg.insertAdjacentHTML('beforeend',`<circle cx="${x(i)}" cy="${y(v)}" r="6" fill="${color}" stroke="white" stroke-width="2"><title>${year.year} · ${periods[i][1]}: ${Number(v).toFixed(1)} ${metrics[metric]} · ${valid}/${w.expected_days} valid days</title></circle>`)}});
 });
 const legend=data.results.map((year,i)=>`<span class="diwali-legend-item"><i style="background:${colors[i%colors.length]}"></i>${year.year}</span>`).join('');
 $('#diwali-legend').innerHTML=legend;$('#diwali-chart-label').textContent=`${metrics[metric]} · mean per period`;
}
function renderHistorical(data){
 const metrics=['pm25','pm10','aqi'],labels={pm25:'PM₂.₅',pm10:'PM₁₀',aqi:'AQI'};
 const summary=metrics.map(m=>`<p><b>${labels[m]}:</b> ${esc(data.summary[m].message)}</p>`).join('');
 const fmt=(w,m,key)=>{const item=w.metrics[m],value=item?.[key];if(value==null)return '—';const digits=m==='aqi'?0:1;return `${Number(value).toFixed(digits)}${key==='mean'?` <small>(${item.valid_days}/${w.elapsed_days} observed days)</small>`:''}`};
 const changeText=(y,m)=>{const c=y.comparisons[m];if(c.status==='compared')return `${c.change_percent>0?'+':''}${Number(c.change_percent).toFixed(1)}%`+(c.absolute_change===0?' · no change':'');if(c.status==='zero_baseline')return `${c.absolute_change>0?'+':''}${Number(c.absolute_change).toFixed(1)} from zero · % n/a`;return 'Not enough observed days'};
 const rows=data.results.map(y=>`<article class="historical-year"><header><div><h3>${y.year} · Diwali ${y.festival_date}</h3><small><span class="data-kind observed">Observed</span> Daily station records · local reference date</small></div></header><div class="table-wrap"><table class="community-table historical-results-table"><thead><tr><th>Period / range</th><th>PM₂.₅ mean / peak</th><th>PM₁₀ mean / peak</th><th>AQI mean / peak</th><th>Days observed</th><th>Missing days</th><th>Future days</th></tr></thead><tbody>${[['before','Before'],['during','Diwali day'],['after','After']].map(([k,label])=>{const w=y.windows[k],upcoming=w.status==='upcoming';return `<tr><td>${label}<br><small>${w.start}${w.end===w.start?'':' to '+w.end}</small></td><td>${upcoming?'Upcoming':`${fmt(w,'pm25','mean')} <span class="stat-separator">/</span> ${fmt(w,'pm25','max')}`}</td><td>${upcoming?'Upcoming':`${fmt(w,'pm10','mean')} <span class="stat-separator">/</span> ${fmt(w,'pm10','max')}`}</td><td>${upcoming?'Upcoming':`${fmt(w,'aqi','mean')} <span class="stat-separator">/</span> ${fmt(w,'aqi','max')}`}</td><td>${w.observed_days}/${w.elapsed_days}</td><td>${w.missing_days}</td><td>${w.future_days}</td></tr>`}).join('')}</tbody></table></div><div class="year-change"><b>Diwali-day mean vs. before-period mean</b>${metrics.map(m=>`<span><b>${labels[m]}:</b> ${changeText(y,m)}</span>`).join('')}</div>${['before','during','after'].map(k=>{const w=y.windows[k];if(w.status==='upcoming')return `<p class="data-warning">${k==='during'?'Diwali day is upcoming':'This window has not started'}; future values are not shown as historical observations.</p>`;if(w.status==='no_data')return `<p class="data-warning">No observations for ${k} (${w.start} to ${w.end}). Missing data is not treated as zero.</p>`;const urls=(w.source_urls||[]).map(url=>`<a href="${esc(url)}" target="_blank" rel="noopener">Source link</a>`).join(' · ');const partial=w.future_days?` ${w.future_days} day(s) are still future.`:'';return `<small class="provenance-line"><span class="data-kind observed">Observed</span> ${k}: ${w.start} to ${w.effective_end||w.end}; ${w.observed_days}/${w.elapsed_days} elapsed dates present; ${w.missing_days} elapsed date(s) missing.${partial} PM₂.₅ ${w.metrics.pm25.valid_days}/${w.elapsed_days}, PM₁₀ ${w.metrics.pm10.valid_days}/${w.elapsed_days}, AQI ${w.metrics.aqi.valid_days}/${w.elapsed_days} valid days. Station ${esc(data.station)} · source: ${esc((w.sources||[]).join(', ')||'not supplied')}${urls?` · ${urls}`:''}. ${esc(w.provenance)}</small>`}).join('')}</article>`).join('');
 return `<section class="smart-summary"><div class="eyebrow">SUMMARY FROM OBSERVED DATA</div>${summary}<small>Mean change compares each year’s Diwali-day mean with that year’s before-period mean. A percentage is shown only when both means exist and the baseline is above zero. This is descriptive, not proof of cause.</small></section><article class="page-card historical-chart-card"><div class="chart-heading"><div><h3>Pollution around Diwali</h3><p>Daily station observations, aligned to each year’s Diwali date.</p></div><label>Pollutant<select id="diwali-metric" class="control" aria-label="Choose pollutant for chart"><option value="pm25">PM₂.₅ · µg/m³</option><option value="pm10">PM₁₀ · µg/m³</option><option value="aqi">AQI · unitless</option></select></label></div><div class="diwali-chart-wrap"><svg id="diwali-chart" role="img" aria-label="Observed pollutant averages before, during, and after Diwali"></svg></div><div class="diwali-chart-caption"><span id="diwali-chart-label">Observed daily mean by period</span><div id="diwali-legend" aria-label="Selected years"></div></div><small class="chart-missing-note">Gaps mean no valid observation was available. Hover or focus a point for its value and valid-day count.</small></article>${rows||'<div class="empty-card"><h3>No comparison data</h3><p>Import verified daily station records for at least two selected years. No sample numbers are included.</p></div>'}`
}

function whatIfPage(){$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow"><span class="data-kind scenario">Scenario</span> · A SIMPLE EXPLORER</div><h2>What If...?</h2><p>Try changing an assumption and see whether the current model can support it. We won’t show a made-up result.</p></section><article class="page-card"><div class="scenario-preset"><button class="btn btn-outline" data-preset="wind">What if wind changes?</button><button class="btn btn-outline" data-preset="rain">What if rain arrives?</button><button class="btn btn-outline" data-preset="emissions">What if emissions change?</button></div><form id="scenario-form"><label>Wind speed change (m/s)<input class="control" name="wind_delta" type="number" min="-3" max="3" value="0"></label><label>Temperature change (°C)<input class="control" name="temperature_delta" type="number" min="-5" max="5" value="0"></label><label>Humidity change (%)<input class="control" name="humidity_delta" type="number" min="-15" max="15" value="0"></label><label>Rainfall change (mm)<input class="control" name="rainfall_delta" type="number" min="0" max="30" value="0"></label><label>Hypothetical emission reduction (%)<input class="control" name="emission_reduction" type="number" min="0" max="100" value="0"></label><button class="btn btn-primary">Explore this scenario</button></form><div class="notice">Scenario results are hypothetical model outputs, not guaranteed real-world outcomes. An observational model cannot confirm the real-world effect of an emissions intervention.</div><div id="scenario-result"><p>${store.aq?.status==='available'?'Current provider data is available; scenario support still depends on the model.':'Air forecast is currently unavailable, so no scenario comparison can be generated.'}</p></div></article>`;$$('[data-preset]').forEach(b=>b.onclick=()=>{let f=$('#scenario-form');if(b.dataset.preset==='wind')f.wind_delta.value=2;if(b.dataset.preset==='rain')f.rainfall_delta.value=5;if(b.dataset.preset==='emissions')f.emission_reduction.value=20});$('#scenario-form').onsubmit=async e=>{e.preventDefault();let body=Object.fromEntries(new FormData(e.target));for(let k in body)body[k]=Number(body[k]);try{let d=await api('/api/simulate',json('POST',body));$('#scenario-result').innerHTML=d.status==='baseline_only'?`<div class="empty-card"><h3><span class="data-kind scenario">Scenario unavailable</span></h3><p>No changed scenario was calculated. The API returned a baseline forecast only; it does not estimate effects of the selected change.</p><p>Forecast values are generated by ${esc(d.baseline?.[0]?.source||'the configured provider')}, not by a validated intervention model.</p></div>`:`<pre>${esc(JSON.stringify(d,null,2))}</pre>`}catch(err){$('#scenario-result').innerHTML=`<div class="empty-card"><h3>We can’t model that scenario yet</h3><p>${esc(err.message)}</p><p>Available air forecast status: ${esc(store.aq?.status||'unavailable')}.</p></div>`}}}
function mapPage(){api('/api/stations').then(ss=>{$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">STATION LOCATIONS</div><h2>Explore the Map</h2><p>Only locations supplied with imported station data can appear here. A station reading does not represent every street nearby.</p></section><article class="page-card">${ss.length?`<div class="station-list">${ss.map(s=>`<div class="station-card"><span class="map-pin">⌖</span><b>${esc(s.station)}</b><span>${s.latitude&&s.longitude?esc(s.latitude+', '+s.longitude):'Coordinates not provided'}</span><small>${s.records} imported records · station measurements</small></div>`).join('')}</div>`:'<div class="empty-card"><h3>No station locations available yet</h3><p>Import station observations with actual coordinates to see them here. Modelled air-quality grid estimates are not monitoring stations.</p></div>'}</article>`})}
function alertsPage(){api('/api/alerts').then(a=>{$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">YOUR AIR UPDATES</div><h2>My Alerts</h2><p>This page reports whether alert rules are configured. Automatic monitoring and threshold rules are not active in this local version.</p></section><article class="page-card"><div class="empty-card"><div>♧</div><h3>No active air alerts</h3><p>${esc(a.status)}. ${a.data_status==='unavailable'?'Live provider data is currently unavailable.':''}</p></div><div class="notice">No automatic monitoring, threshold rules, staffed moderation, push notifications, SMS, or WhatsApp delivery is connected. Login is not available in this local community space.</div></article>`})}
function progressPage(){Promise.all([api('/api/community/progress?user_id='+encodeURIComponent(store.userId)),api('/api/community/impact'),api('/api/community/leaderboard?scope=individual&period=overall')]).then(([p,i,lb])=>{$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">YOUR GREEN DIWALI</div><h2>My Progress</h2><p>Your points come from saved participation. They are not a measure of pollution reduction.</p></section><div class="impact-grid"><article><b>${p.points}</b><span>participation points</span></article><article><b>${p.completed_challenges.length}</b><span>challenges completed</span></article><article><b>${p.joined_communities.length}</b><span>communities joined</span></article><article><b>${p.pledged?'Yes':'Not yet'}</b><span>Green Diwali pledge</span></article></div><article class="page-card"><h3>Communities you’ve joined</h3>${p.joined_communities.length?p.joined_communities.map(c=>`<p>${esc(c.name)} · ${esc(c.city)}</p>`).join(''):'<p>You haven’t joined a community yet.</p>'}<button class="btn btn-outline" data-go="community">Explore Green Community</button></article><article class="page-card"><h3>Community participation</h3><p>${i.members} joined members · ${i.pledges} pledges · ${i.completed_challenges} completed challenges · ${i.events_organised} events created · ${i.event_participations} event participations · ${i.points_earned} points earned</p><small>${esc(i.note)}</small></article></div>`;$('#detail').querySelector('[data-go]').onclick=()=>page('community')})}
function sciencePage(v){Promise.all([api('/api/data-sources'),api('/api/model/performance'),api('/api/model/explanations')]).then(([s,m,e])=>{$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">SCIENCE & DATA · DETAILS FOR CURIOUS MINDS</div><h2>${titles[v][0]}</h2><p>We keep technical details here so the main experience stays simple.</p></section><article class="page-card"><h3>Where the air data comes from</h3><pre>${esc(JSON.stringify(s,null,2))}</pre><p>Live modelled estimates and imported observations are different data types. AQI requires a valid supported source and averaging period; it is unavailable in the current data.</p></article><article class="page-card"><h3>Local model evaluation</h3><pre>${esc(m.status==='evaluated'?JSON.stringify(m.metrics,null,2):'Not evaluated. No local model is trained yet. Import at least 30 dated observations and run the training command.')}</pre><small>Underlying training method: Random Forest. Error values are shown only after actual chronological holdout evaluation.</small></article><article class="page-card"><h3>Why is this happening?</h3><pre>${esc(JSON.stringify(e,null,2))}</pre><p>Feature importance describes patterns in historical data; it does not prove what caused pollution.</p></article><article class="page-card"><h3>Community data & privacy</h3><p>Community participation is stored in a local SQLite database. Display names and local profile identifiers are self-declared because sign-in is not set up. Do not share sensitive personal details.</p></article>`})}
function authorityPage(){Promise.all([api('/api/stations'),api('/api/air-quality/latest'),api('/api/data-sources'),api('/api/alerts')]).then(([stations,air,sources,alerts])=>{$('#detail').innerHTML=`<section class="page-intro"><div class="eyebrow">CITY ACTION CENTRE · LOCAL PROTOTYPE</div><h2>Monitoring overview</h2><p>This is an informational prototype. It is not an official city system and does not automate enforcement.</p></section><div class="impact-grid"><article><b>${stations.length}</b><span>imported station names</span></article><article><b>${sources.providers[1]?.records||0}</b><span>imported observations</span></article><article><b>${air.status==='available'?'Available':'Unavailable'}</b><span>regional model forecast</span></article><article><b>${alerts.alerts.length}</b><span>active in-app alerts</span></article></div><article class="page-card"><h3>Station data provided</h3>${stations.length?`<div class="station-list">${stations.map(s=>`<div class="station-card"><span class="map-pin">⌖</span><b>${esc(s.station)}</b><span>${s.latitude&&s.longitude?esc(s.latitude+', '+s.longitude):'Coordinates not provided'}</span><small>${s.records} imported records</small></div>`).join('')}</div>`:'<p>No station records imported.</p>'}</article><article class="page-card"><h3>Current regional model output</h3><p>${air.current?`PM₂.₅ ${Number(air.current.pm25).toFixed(1)} and PM₁₀ ${Number(air.current.pm10).toFixed(1)} µg/m³ at ${esc(air.current.timestamp)}.`:'No regional forecast available.'}</p><small>Open-Meteo modelled grid estimate, not a station measurement.</small></article><article class="page-card"><h3>Export imported observations</h3><p>Download the measurements that were imported into this local app.</p><a class="btn btn-outline" href="/api/reports/export">Download CSV</a></article>`})}
async function loadAir(){try{store.aq=await api('/api/air-quality/latest');let a=store.aq;$('#provider-status').textContent=a.provider_status==='available'?'Connected':a.current?.kind==='observed'?'Imported data':'Unavailable';$('#freshness').textContent=a.current?`${a.current.kind==='observed'?'Observed':'Air update'} · ${a.current.timestamp}`:'Latest air update unavailable';$('#location-label').textContent='⌖  '+(a.location||'Delhi, India');if(a.current){const kind=a.current.kind||a.data_kind||'estimated',label=kind==='observed'?'Observed':kind==='forecast'?'Forecast':'Estimated';$('#data-badge').textContent=label.toUpperCase();$('#air-reading').innerHTML=`<strong>${Number(a.current.pm25).toFixed(1)}</strong><span>µg/m³ · PM₂.₅ ${label.toLowerCase()}</span>`;$('#air-explanation').textContent=kind==='observed'?'Imported station observation; source and station identity are uploader-supplied.':kind==='forecast'?'Open-Meteo forecast for a wider area, not a nearby sensor measurement.':'Open-Meteo model estimate for a wider area, not a nearby sensor measurement.';$('#updated-at').textContent=`${label} · ${a.current.timestamp} · ${a.current.source||a.source||'source unavailable'} · ${a.current.location||a.location||'location unavailable'}`;$('#air-advice').textContent='Check local air before outdoor activity. Follow public-health advice if you have breathing concerns.'}else{$('#data-badge').textContent='NO LATEST READING';$('#air-reading').innerHTML='<strong>—</strong><span>AQI unavailable</span>';$('#air-explanation').textContent='We couldn’t retrieve the latest air quality reading. Please try again later.';$('#updated-at').textContent='No reading available';$('#air-advice').textContent='No local AQI category is available. Check your local public-health service for current advice.'}let tomorrowForecast=a.tomorrow_forecast;if(tomorrowForecast?.hours){$('#tomorrow-summary').textContent=`PM₂.₅ forecast: ${Number(tomorrowForecast.pm25_mean).toFixed(1)} µg/m³`;$('#tomorrow-detail').textContent=`${a.source||'Open-Meteo'} · ${a.location||'Location unavailable'} · ${tomorrowForecast.date}: hourly model estimates range from ${Number(tomorrowForecast.pm25_min).toFixed(1)} to ${Number(tomorrowForecast.pm25_max).toFixed(1)} µg/m³ (${tomorrowForecast.hours} forecast hours). Forecast, not a sensor measurement.`}else{$('#tomorrow-summary').textContent='Forecast unavailable';$('#tomorrow-detail').textContent='We couldn’t retrieve a complete forecast for tomorrow. No prediction has been substituted.'}if($('#detail').style.display!=='none'&&$('#title').textContent==='Check Your Air')airPage()}catch(e){$('#provider-status').textContent='Unavailable';$('#freshness').textContent='Latest air update unavailable';$('#air-explanation').textContent='We couldn’t retrieve the latest air quality reading. Please try again later.'}}
$$('#nav button').forEach(b=>b.onclick=()=>page(b.dataset.view));$$('.science-nav button,.authority-link').forEach(b=>b.onclick=()=>page(b.dataset.view));$$('[data-go]').forEach(b=>b.onclick=()=>page(b.dataset.go));$('#refresh').onclick=loadAir;loadAir();
api('/api/community/pledges').then(x=>$('#home-pledges').textContent=x.count).catch(()=>$('#home-pledges').textContent='0');api('/api/community/impact').then(x=>$('#home-challenges').textContent=x.completed_challenges).catch(()=>$('#home-challenges').textContent='0');
